window.deepArticles = window.deepArticles || {};

const networkHistorySources = [
  {href:"../settingBible%20-%20AltWWII.md",label:"Setting Bible — computing and global networks"},
  {href:"../settingTimeline%20-%20AltWWII.md",label:"Setting Timeline — network convergence"},
  {href:"../transcript.md",label:"Master Transcript — Weltnetz architecture and network culture"},
  {href:"../SoftwareDetailReference.md",label:"Software and Programming Language Reference"},
  {href:"../materialCultureReference%20-%20AltWWII.md",label:"Material Culture Reference — telecommunications and household computing"}
];

const networkArticle = config => ({
  category:"Computing",
  eyebrow:"Network history · alternate-world reference",
  infoboxKicker:"Global network system",
  ...config,
  sources:[...networkHistorySources,...(config.primarySources || [])],
  categories:config.categories || ["Computing","Computer networks","Weltnetz","Technology history"]
});

Object.assign(window.deepArticles,{
  "weltnetz":networkArticle({
    slug:"weltnetz",title:"Weltnetz",eyebrow:"Common international network layer · from the 1980s",infoboxKicker:"German-led global internetwork",
    lead:"Weltnetz is the common civilian and commercial network layer that emerges from Germany’s satellite-centered imperial network and becomes the world standard during the 1990s. It connects national systems without replacing their computers, software, laws, search services, or political boundaries—and its adopted transport protocol does not enforce the universal identity imagined by its principal architect, Matthias Falkenberg.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-n1a2b writer=g kind=revision created=2026-08-15T22:55:00-06:00 -->Falkenberg's 1979 public vision, the 1981 study and 1982 commission, Weltnetz's satellite-centered hybrid architecture, compactness, redundancy and caching, German–Japanese convergence, native UNICODE 80 support, Bridge-led American adoption, post-1985 network-layer victory, and absence of mandatory real identity in the base protocol are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Public-trial dates, the detailed packet and repair mechanisms, exact convergence sequence, Bridge/WN and Concord release dates, the date at which Weltnetz became the default global family, low-level protocol names, addresses, and carriers remain working detail.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"origins",title:"From imperial administration to world network",html:"<p>German networking begins in military command, aerospace, railways, commodity administration, banks, industrial combines, and <a href='mosaik-system.html'>MOSAIK</a>. Falkenberg’s 1979 ‘Computing Without Distance’ lecture argues that the same federated machinery can connect firms, universities, households, satellites, and foreign partner networks without forcing them onto one computer family.</p>"},
      {id:"architecture",title:"Satellite-centered, not satellite-only",html:"<p>Dense traffic moves through cable, microwave, fiber, and local packet systems. Geostationary trunks, polar and highly elliptical relays, and lower-orbit store-and-forward satellites extend reach to ships, the Arctic, Siberia, Africa, and politically isolated regions. Space infrastructure supplies universality and fallback rather than carrying every nearby transaction.</p>"},
      {id:"compact",title:"Compactness, repair, and caching",html:"<p>The adopted family uses short fixed headers, optional extensions, segmentation, sequence control, error checks, hop-by-hop repair on unreliable routes, end-to-end validation by applications, queued delivery, and duplicate carriage only for priority traffic. Regional mirrors and incremental updates keep a Mittelafrican office from retrieving every authorized document directly from Berlin.</p>"},
      {id:"identity",title:"The identity compromise",html:"<p>Falkenberg assumes registered machines, certified gateways, known institutions, and identifiable subscribers. The successful transport standard proves only technical addresses and message reconstruction. Providers may know which customer entered through a gateway, and banks or ministries demand signed credentials, but packets do not contain mandatory proof of civil identity.</p><p>The address is a return address, not a passport.</p>"},
      {id:"japan",title:"German–Japanese convergence",html:"<p>Implementation of the <a href='tehran-concord.html'>Tehran Concord</a> opens convergence after 1985. Japan brings native <a href='unicode-80.html'>UNICODE 80</a> identity, vertical and horizontal layout, paging, delayed delivery, compact terminals, and household services. Japanese users encounter the shared network as <a href='japanese-imperial-information-network.html'>Sekaimō</a>, but its packet family remains Weltnetz.</p>"},
      {id:"america",title:"Bridge makes it global",html:"<p><a href='bridge-wn.html'>Bridge/WN</a> gives the decentralized American compatible market direct access in 1988; Concord follows with a curated gateway in 1989. Civilian American Data Network infrastructure increasingly carries Weltnetz traffic, while the protected American strategic backbone retains separate protocols and controlled links.</p>"},
      {id:"control",title:"Germany controls the map",html:"<p>German providers identify customers, log access, favor a restrictive national directory, warn against unregistered services, and block known hostile destinations. None of this makes the underlying transport fully controllable. Direct addresses, foreign directories, relays, dynamic services, encrypted payloads, shared terminals, and compromised machines turn attribution into investigation rather than an automatic protocol fact.</p>"},
      {id:"position",title:"The common layer by the mid-1990s",html:"<p>Weltnetz wins carriage rather than the whole computing world. German, Japanese, American, Commonwealth, and Latin hardware, operating systems, applications, strategic networks, publishers, and <a href='national-network-search-services.html'>search systems</a> remain distinct. Germany builds the road; other societies decide what usually appears along it.</p>"}
    ],
    related:[{href:"computing-networks.html",kicker:"Comparative history",label:"Computing and Global Networks"},{href:"matthias-falkenberg.html",kicker:"Principal architect",label:"Matthias Falkenberg"},{href:"seitenplan.html",kicker:"Document standard",label:"Seitenplan"},{href:"bridge-wn.html",kicker:"American gateway",label:"Bridge/WN"},{href:"shadownet.html",kicker:"Unlisted overlay",label:"ShadowNet"}],
    facts:[["Architect","Matthias Falkenberg"],["Concept lecture","1979"],["Formal German study","1981"],["Public trials","Working chronology: 1983–1985"],["Architecture","Terrestrial and satellite hybrid"],["Mandatory transport identity","Absent"],["American commercial gateway","Bridge integration, late 1980s"],["Global civilian standard","Post-1985; exact date open"]]
  }),

  "seitenplan":networkArticle({
    slug:"seitenplan",title:"Seitenplan",eyebrow:"Working Weltnetz document-language reconstruction",infoboxKicker:"Proposed declarative network-document standard",
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260815-n2c3d writer=g kind=revision created=2026-08-15T22:55:00-06:00 --><strong>Seitenplan</strong> (‘Page Plan’) is the working reconstruction of Weltnetz's German-led document and service-description language. Canon establishes a German display standard drawing probably from Rechenplan or Kurzplan and supplying German-derived network vocabulary; the name, 1988 edition, ancestry, token model, and security boundary below remain extrapolation.<sup class='canon-note' data-provenance='a'>[a]</sup><sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-n9t1u writer=g kind=revision created=2026-08-15T22:55:00-06:00 -->The existence of a German-origin Weltnetz display language, its probable relationship to Rechenplan or Kurzplan, and the spread of German equivalents of terms such as page and window are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Seitenplan as its name, Seitenplan 88, the exact vocabulary, multilingual tokens, institutional contributions, declarative-only boundary, grammar, rendering, and later scripting family remain working design.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"need",title:"A common document above unlike machines",html:"<p>Weltnetz can carry bytes between systems without telling a Japanese household terminal, British library screen, German office station, or American Bridge machine how to display the same public document. Seitenplan standardizes structure and capability negotiation without choosing one bloc’s operating system.</p>"},
      {id:"ancestry",title:"Institutional ancestry",html:"<p><a href='rechenplan.html'>Rechenplan</a> contributes explicit structure, validation, reproducibility, and separation of content from operation. <a href='kurzplan.html'>Kurzplan</a> contributes compact authoring and small-machine implementation. Japan contributes script direction and page segmentation; Britain contributes device-independent presentation; Latin systems contribute structured forms and public-database interaction.</p>"},
      {id:"vocabulary",title:"German normative vocabulary",html:"<div class='table-wrap'><table class='wiki-table'><thead><tr><th>Term</th><th>Meaning</th></tr></thead><tbody><tr><td>Seite</td><td>Page or document</td></tr><tr><td>Fenster</td><td>Independent display region</td></tr><tr><td>Verweis</td><td>Link or reference</td></tr><tr><td>Bild</td><td>Image</td></tr><tr><td>Tabelle</td><td>Table</td></tr><tr><td>Formular</td><td>Interactive form</td></tr><tr><td>Dienst</td><td>Network service</td></tr><tr><td>Netzstelle</td><td>Network site or location</td></tr><tr><td>Abruf</td><td>Request or retrieval</td></tr></tbody></table></div>"},
      {id:"tokens",title:"Tokenized interchange",html:"<p>The transmitted representation stores logical structural tokens rather than requiring every author to type German words. A Japanese editor may show localized terms and vertical layout while emitting the same tokens as an Italian or American tool. Standards manuals retain the German names, giving international programmers a recognizable technical vocabulary.</p>"},
      {id:"unicode",title:"Script and device independence",html:"<p>UNICODE 80 character identities, writing-direction declarations, line-breaking metadata, page segments, fonts, images, and device-capability descriptions prevent Latin horizontal display from becoming the invisible assumption of the global network. Compact local encodings remain permissible where gateways preserve identity.</p>"},
      {id:"forms",title:"Pages, forms, and services",html:"<p>A page may contain text, images, tables, references, updating windows, and structured forms. Interactive work is normally submitted to a named server-side service or a locally installed application. Seitenplan describes the exchange without pretending that every bank, ministry, shop, or database follows the same internal rules.</p>"},
      {id:"security",title:"Declarative by design",html:"<p>Early editions do not automatically download arbitrary publisher code. Germany treats unknown executable content as a security and authority problem. Later interactive modules are locally installed, signed, or invoked as remote services; a proposed Kurzplan-derived scripting family remains more contested than the document standard itself.</p>"},
      {id:"legacy",title:"International legacy",html:"<p>Seitenplan spreads with Bridge/WN and Concord support after 1988–89. Users still say page, window, and link in ordinary speech, while programmers borrow Seite, Fenster, and Verweis from the specification. The result is a German technical layer whose public face can remain fully Japanese, English, Spanish, or another language.</p>"}
    ],
    related:[{href:"weltnetz.html",kicker:"Transport system",label:"Weltnetz"},{href:"unicode-80.html",kicker:"Character identity",label:"UNICODE 80"},{href:"bridge-wn.html",kicker:"American implementation",label:"Bridge/WN"},{href:"rechenplan.html",kicker:"Structural ancestor",label:"Rechenplan"},{href:"kurzplan.html",kicker:"Compact ancestor",label:"Kurzplan"}],
    facts:[["Working name","Seitenplan (Page Plan)"],["Proposed international edition","Seitenplan 88"],["System","Weltnetz"],["Proposed form","Declarative tokenized document"],["Character identity","UNICODE 80"],["Established origin","German"],["Downloaded-code rule","Working design"],["Complete grammar","Open"]]
  }),

  "bridge-wn":networkArticle({
    slug:"bridge-wn",title:"Bridge/WN",eyebrow:"Working name for Interlink's late-1980s network environment",infoboxKicker:"American Weltnetz compatibility layer",
    lead:"<!-- altwwii-writer-block:start id=wb-g-20260815-n3e4f writer=g kind=revision created=2026-08-15T22:55:00-06:00 --><strong>Bridge/WN</strong> is the working name for Interlink Software's late-1980s Weltnetz environment for Bridge. Interlink's commercial decision to make Bridge interoperate with the German–Japanese system—and the decisive role this plays in bringing Weltnetz into the United States—is established; the 1988 date, product name, service list, and implementation remain reconstruction.<sup class='canon-note' data-provenance='a'>[a]</sup><sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-p1v2w writer=g kind=revision created=2026-08-15T22:55:00-06:00 -->Interlink's late-1980s decision to integrate Bridge with Weltnetz for commercial access, the resulting American adoption, and Concord's comparable commercial response are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Bridge/WN as the product name, a 1988 release, Keene's exact rationale, the listed services, developer interfaces, UNICODE and Seitenplan packaging, ADN migration mechanics, Concord's 1989 date, versioning, pricing, language, and IBM bundling remain working detail.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"problem",title:"The international compatibility problem",html:"<p>Bridge applications can move among many American-compatible machines, but before 1988 they still encounter incompatible international carriers and gateways. A German–Japanese network spanning Europe, northern Asia, the Pacific, and Southeast Asia is too large for exporters, banks, publishers, and software firms to treat as a specialist foreign connection.</p>"},
      {id:"keene",title:"Martin Keene’s decision",html:"<p><a href='martin-keene.html'>Martin Keene</a> does not adopt Weltnetz from sympathy with Germany. His argument is that a general-purpose environment does not acquire a foreign policy because a packet crosses a border. Stable interfaces should let customers reach the largest available market.</p>"},
      {id:"services",title:"Service environment",html:"<p>Bridge/WN supplies international addressing, subscriber and application authentication, mail, queued messages, file transfer, directory lookup, Seitenplan display, character conversion, and translation between Bridge file conventions and Weltnetz services. Authentication is available to applications without becoming mandatory proof inside every packet.</p>"},
      {id:"developers",title:"A programmable medium",html:"<p>The decisive change is not merely access. American developers can build mail clients, bulletin boards, file servers, relays, multiplayer games, publishers, and private directories through stable Bridge interfaces without seeking certification from the German network commission.</p>"},
      {id:"unicode",title:"UNICODE and document interchange",html:"<p>Bridge/WN makes UNICODE 80 conversion and Seitenplan display normal parts of foreign connectivity. American software can preserve Japanese, Chinese, Korean, Khmer, Lao, Hán–Nôm, and European text identities even where local files and screens still use narrower encodings.</p>"},
      {id:"adn",title:"Migration from the ADN",html:"<p>American Data Network cables, switches, university links, and commercial providers remain in place but increasingly transport Weltnetz traffic. Firms prefer one route to foreign customers over bespoke protocol translation. The 1990 crash and export drive remove much of the political appetite for subsidizing a parallel civilian standard.</p>"},
      {id:"concord",title:"Concord follows",html:"<p>Elias Mercer first favors a proprietary curated gateway. Customer demand forces Concord to introduce certified Weltnetz support in 1989 while preserving its own interface, publisher rules, parental controls, signed objects, and content stores. Once both Bridge and Concord speak Weltnetz, the American civilian protocol contest is effectively decided.</p>"},
      {id:"compatibility-market",title:"Compatibility market and control",html:"<!-- altwwii-writer-block:start id=wb-r-20260816-m7c3q writer=r kind=analysis created=2026-08-16T14:01:00-06:00 --><p>Interlink's compatibility decision was an entrepreneurial judgment about an unmet market. American users already owned computers, software, files, and carrier relationships; foreign customers and suppliers were increasingly reachable through Weltnetz. A translation environment could preserve that installed capital while selling access to a larger network. Its value came from reducing the cost of switching standards, not from replacing every American machine or link.</p><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Layer</th><th>Customer cost or asset preserved</th><th>Entry and control test</th></tr></thead><tbody><tr><td>Bridge environment</td><td>Licence, installation, training, support, and existing applications or files retained</td><td>Whether another implementer could use documented interfaces or users depended upon Interlink for every revision</td></tr><tr><td>Network translation</td><td>Addressing, character conversion, directories, messages, files, display, authentication, and failure handling</td><td>Whether translation exposed errors and service limits or concealed them behind a nominal connection</td></tr><tr><td>Carrier and gateway access</td><td>Connection time, capacity, foreign settlement, routing, and service eligibility</td><td>Whether Bridge/WN could choose among carriers and gateways on published terms</td></tr><tr><td>Application and hosting market</td><td>Development tools, distribution, foreign customers, maintenance, and platform switching</td><td>Whether independent services could enter without Interlink or foreign certification defining their commercial content</td></tr></tbody></table></div><p>Stable Bridge interfaces let independent developers build services without negotiating every application with the foreign network authority. That separation created a market above the carriage standard. It remained open only if interface documentation, protocol rights, character conversion, directory access, and gateway terms could be implemented or challenged by other suppliers. A proprietary extension that became necessary for reach could turn the translator into a new gatekeeper while retaining the language of compatibility.</p><p>Adoption also created switching costs. Firms trained staff, converted files, changed addresses, rewrote applications, and accumulated customers and reputation on the common network. Those investments made later exit expensive even when another protocol became technically superior. Competition from Concord, direct Weltnetz implementations, carrier tools, and retained ADN services could discipline Interlink if users could move data, addresses, contracts, and applications among them.</p><p>Dependence upon a German-led standard did not make the American activity economically passive. American developers, hosts, carriers, and customers could create most of the services and value reached through Bridge/WN. Foreign control mattered at the standard, directory, certification, and international-route boundaries. Exact product name and release date, licence price, development cost, interface rights, patents, certification, gateway fees, carrier choice, migration cost, market shares, failures, and government or procurement support remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"legacy",title:"Commercial consequence",html:"<p>Bridge/WN gives American independent software and hosting international reach while simultaneously making American civilian networking dependent upon a German-led standard. It is the moment Weltnetz stops being merely the largest foreign system and becomes the common commercial road.</p>"}
    ],
    related:[{href:"bridge-operating-environment.html",kicker:"Parent platform",label:"Bridge Operating Environment"},{href:"weltnetz.html",kicker:"Network standard",label:"Weltnetz"},{href:"martin-keene.html",kicker:"Architect",label:"Martin Keene"},{href:"seitenplan.html",kicker:"Document support",label:"Seitenplan"},{href:"american-data-network.html",kicker:"Displaced civilian protocol",label:"American Data Network"}],
    facts:[["Developer","Interlink Software Corporation"],["Release","Late 1980s; 1988 is working"],["Principal architect","Martin Avery Keene"],["Parent platform","Bridge"],["Network family","Weltnetz"],["Product name","Bridge/WN is working"],["Service package","Working reconstruction"],["Motive","Commercial interoperability"]]
  }),

  "american-data-network":networkArticle({
    slug:"american-data-network",title:"American Data Network",eyebrow:"United States packet-network family · late 1960s–1990s",infoboxKicker:"American institutional network",
    lead:"The American Data Network (ADN) is the decentralized family of university, defense, aerospace, government, banking, media, and commercial packet networks that forms the United States’ native digital infrastructure. It pioneers open experimentation and continental service but loses the global civilian protocol contest to Weltnetz, surviving most purely as a protected strategic backbone.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-n4g5h writer=g kind=revision created=2026-08-15T22:55:00-06:00 -->The American Data Network's defense and university origins, relatively open and decentralized character, early-1980s expansion into banks, contractors, government records, electronic newspapers and local boards, later civilian migration onto Weltnetz through Bridge, and eventual restriction of its surviving lineage to strategic and military use are established.<sup class='canon-note' data-provenance='a'>[a]</sup> A late-1960s starting date, the complete institutional list, international technical shortcomings, post-1990 migration mechanics, exact protected functions, federal charter, protocols, backbone name, ownership, and dates remain working history.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"origins",title:"Research and defense origins",html:"<p>The ADN begins among military research establishments, universities, aerospace contractors, computer manufacturers, and government laboratories during the late 1960s and early 1970s. Decentralization, survivability, general-purpose machines, and relatively open technical exchange shape its first culture.</p>"},
      {id:"growth",title:"Civilian expansion",html:"<p>By the early 1980s packet links connect banks, government records, electronic newspapers, contractors, research libraries, and local dial-up boards. The same infrastructure carries games, programs, political pamphlets, rumors, and assassination theories that national broadcast institutions cannot easily contain.</p>"},
      {id:"strength",title:"Continental strength",html:"<p>The system is fast and adaptable inside the United States because many compatible computers and competing carriers can join it. Universities and firms treat new applications as experiments rather than privileges requiring one national service charter.</p>"},
      {id:"weakness",title:"International weakness",html:"<p>The ADN grows as linked American institutions rather than a planned international administrative architecture. Foreign character sets, directories, billing, authentication, currencies, and associated-state gateways accumulate unevenly. A California laboratory is easier to connect than a provincial Manchukuoan office using Japanese text and imperial settlement accounts.</p>"},
      {id:"bridge",title:"Bridge and Weltnetz",html:"<p>Interlink’s <a href='bridge-wn.html'>Bridge/WN</a> environment lets American machines use the emerging German–Japanese standard without abandoning local hardware. Commercial providers discover that they can retain their switches and customer relationships while adopting a common foreign-facing packet family.</p>"},
      {id:"migration",title:"Civilian migration after 1990",html:"<p>The Open Door Depression makes export access urgent and parallel protocol subsidies unpopular. ADN civilian carriers increasingly become domestic portions of Weltnetz, much as a railway may keep its tracks and operators after adopting a common gauge.</p>"},
      {id:"strategic",title:"Strategic survival",html:"<p>The protected original core narrows toward defense, intelligence, aerospace command, emergency government, strategic industry, and secure financial settlement. It is faster and more isolated within the United States, with controlled gateways to the civilian network. ‘Strategic Data Network’ is common descriptive usage, not yet a fixed formal name.</p>"},
      {id:"capital-migration",title:"Capital, access, and migration",html:"<!-- altwwii-writer-block:start id=wb-r-20260816-d4x8p writer=r kind=analysis created=2026-08-16T14:00:00-06:00 --><p>The ADN combined capital supplied by federal research and defense procurement, universities, computer manufacturers, carriers, banks, contractors, and later commercial providers. Open documentation and permission for heterogeneous machines to join lowered the cost of experimentation for firms and users who did not finance the original work directly. That diffusion was a productive return on public and institutional capital, while also making it difficult to assign research cost to the applications and companies that later profited.</p><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Capital or service</th><th>Return created</th><th>Discipline required</th></tr></thead><tbody><tr><td>Research grants and defense procurement</td><td>Packet methods, survivability, software, trained personnel, and an initial network</td><td>Published interfaces, usable results, procurement cost, contractor rights, and access beyond the sponsor</td></tr><tr><td>University and laboratory nodes</td><td>Experimentation, shared computing, applications, and technical labor</td><td>Connection cost, capacity used, security burden, and conditions on private commercialization</td></tr><tr><td>Carrier and commercial access</td><td>Physical reach, billing, support, and admission of banks, media, firms, and local boards</td><td>Interconnection terms, congestion prices, outage records, quality, and entry by another carrier</td></tr><tr><td>Strategic remnant</td><td>Protected command, intelligence, emergency, financial, and industrial communication</td><td>Named mission, annual carrying cost, isolation and restoration tests, gateway risk, and replacement of obsolete components</td></tr></tbody></table></div><p>Open attachment did not remove scarcity. Trunks, switches, modems, gateways, power, support staff, and dial-up lines could congest or fail. A zero or subsidized institutional price could encourage experimentation while concealing the cost imposed on delayed traffic and excluded users. Capacity prices, service classes, published queues, reciprocal interconnection, and outage records allowed carriers and users to distinguish valuable open entry from use financed by an unrelated subscriber or appropriation.</p><p>Civilian migration onto Weltnetz did not make the ADN's physical investment disappear. Cables, switches, local links, customer relationships, and trained operators could carry the new protocol family. The economic loss lay in software, gateways, specialized equipment, administration, and skills that could not be reused, plus the foregone alternatives financed by continued protocol subsidy. Private providers choosing foreign reach supplied evidence about customer demand; the 1990 budget crisis also made the migration occur under financial distress rather than a neutral experiment.</p><p>The strategic remnant could remain worthwhile even if it earned no civilian revenue. Its claim required an explicit readiness account rather than indefinite protection for the original managers, contractors, or protocol. Exercises, attack and outage performance, restoration time, gateway isolation, usable spare capacity, and the cost of equivalent service through another design showed whether the government was buying security or preserving a sunk institutional identity. Exact appropriations, ownership, carrier prices, interconnection rules, congestion, private reuse, stranded assets, protected functions, and backbone organization remain open.</p><!-- altwwii-writer-block:end -->"},
      {id:"legacy",title:"Historical irony",html:"<p>America develops the decentralized culture most capable of filling a global network with software and independent services but does not supply the winning international carriage standard. Its purest national packet lineage returns to the military and governmental setting from which it emerged.</p>"}
    ],
    related:[{href:"weltnetz.html",kicker:"Successor civilian layer",label:"Weltnetz"},{href:"bridge-wn.html",kicker:"Migration mechanism",label:"Bridge/WN"},{href:"shadownet.html",kicker:"Later American culture",label:"ShadowNet"},{href:"bridge-operating-environment.html",kicker:"Compatible platform",label:"Bridge"},{href:"computing-networks.html",kicker:"Comparative setting",label:"Computing and Global Networks"}],
    facts:[["Country","United States"],["Origins","Research, defense, universities"],["Principal period","Late 1960s–early 1990s"],["Strength","Open continental experimentation"],["Weakness","International administration and text"],["Civilian successor","Weltnetz carriage"],["Migration mechanism","Bridge/WN"],["Protected remnant","Strategic backbone"]]
  }),

  "commonwealth-packet-service":networkArticle({
    slug:"commonwealth-packet-service",title:"Commonwealth Packet Service",eyebrow:"Managed information-service network · 1970s–1990s",infoboxKicker:"British and Commonwealth packet system",
    lead:"The Commonwealth Packet Service (CPS) is the managed packet and information-service network connecting British and Commonwealth universities, ports, banks, schools, governments, shipping, insurance, and scientific institutions. Its expertise in unlike machines, translation, and public services makes it an essential gateway culture even after it adopts Weltnetz for external carriage.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-n5j6k writer=g kind=revision created=2026-08-15T22:55:00-06:00 -->A distinct Commonwealth Packet Service exists by 1985 and later retains national services while adopting Weltnetz as an external layer.<sup class='canon-note' data-provenance='a'>[a]</sup> Its 1970s emergence, NPL lineage, managed-service model, exact users, translation specialization, reach constraint, public-information culture, adoption date, gateway economy, tariffs, national subdivisions, and operators remain compatible working development.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"foundation",title:"Packet and service foundations",html:"<p>British time sharing, packet-switching research, public data services, videotex, university computing, and the administrative inheritance of a dispersed Commonwealth form the CPS. It is designed less as a universal hobbyist medium than as a purchasable, accountable information service.</p>"},
      {id:"users",title:"Institutional network",html:"<p>Universities, port authorities, banks, government departments, schools, libraries, shipping lines, insurers, signals establishments, and scientific centers buy access to managed services. National operators retain local laws, schedules, accounts, and equipment while sharing common gateways and directories.</p>"},
      {id:"heterogeneous",title:"Connecting unlike systems",html:"<p>The Commonwealth contains different currencies, ministries, machine families, languages, and levels of infrastructure. British engineers become skilled at protocol conversion, terminal adaptation, character mapping, store-and-forward communication, and clear service contracts rather than assuming every endpoint is the same.</p>"},
      {id:"reach",title:"The problem of physical reach",html:"<p>Britain can connect principal cities, ports, bases, and educational centers, but capital constraints and geography prevent it from matching German satellite-launch volume or Japanese consumer-terminal scale. Remote access often depends on radio, leased circuits, and costly international carriers.</p>"},
      {id:"public",title:"Public information culture",html:"<p>CPS institutions emphasize reference works, libraries, education, transport schedules, public records, professional databases, and accountable publishing. Independent forums exist, but access normally begins through a named institution or subscriber account.</p>"},
      {id:"weltnetz",title:"Adoption of Weltnetz carriage",html:"<p>During the early 1990s the CPS adopts Weltnetz as its principal external internetworking layer. British accounts, educational services, banking, public records, shipping, and legal jurisdiction remain; the packets crossing into Germany, Japan, Latin Europe, or American Bridge networks use the common family.</p>"},
      {id:"gateways",title:"Translation and caching power",html:"<p>Commonwealth operators profit from translating old formats, caching foreign documents, relaying multilingual traffic, and connecting legacy systems. Britain loses the contest to name the world network but retains influence over how institutions traverse it.</p>"},
      {id:"position",title:"Position after convergence",html:"<p>The CPS becomes a national and Commonwealth service ecology above and beneath Weltnetz rather than a failed Internet. Its endurance demonstrates the central feature of convergence: shared carriage does not require one global operator, search engine, publisher, or public law.</p>"}
    ],
    related:[{href:"commonwealth.html",kicker:"Political system",label:"British Commonwealth"},{href:"weltnetz.html",kicker:"External carriage",label:"Weltnetz"},{href:"computing-networks.html",kicker:"Comparative setting",label:"Computing and Global Networks"},{href:"commonwealth-programming-languages.html",kicker:"Software culture",label:"Commonwealth Programming Languages"},{href:"national-network-search-services.html",kicker:"Public discovery",label:"National Network Search Services"}],
    facts:[["Abbreviation","CPS"],["Region","British Commonwealth"],["Emergence","1970s"],["Model","Managed information service"],["Principal users","Government, education, ports, finance"],["Specialty","Gateways and translation"],["Principal limitation","Capital and physical reach"],["External layer after convergence","Weltnetz"]]
  }),

  "japanese-imperial-information-network":networkArticle({
    slug:"japanese-imperial-information-network",title:"Japanese Imperial Information Network",eyebrow:"Factory, transaction, and household network · 1970s–1990s",infoboxKicker:"Japanese imperial network system",
    lead:"The Japanese Imperial Information Network is the pre-convergence network ecology linking factories, banks, trading houses, shipping, railways, paging, households, and associated-state services. Its working formal name is Teikoku Jōhōmō; after convergence, Japanese users encounter the shared Weltnetz family through the localized name Sekaimō.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-n6m7n writer=g kind=revision created=2026-08-15T22:55:00-06:00 -->Japan's distinct pre-convergence imperial network, its strength in electronics, native non-Latin computing, factory and consumer systems, its integration with Weltnetz, and a localized Japanese presentation of the common protocol are established.<sup class='canon-note' data-provenance='a'>[a]</sup> Factory, banking, shipping, paging, household and associated-state details; the 1986–88 sequence; service controls; sphere inequalities; and the names Teikoku Jōhōmō and Sekaimō remain working elaboration rather than immutable institutional history.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"origins",title:"Factories, trade, and imperial logistics",html:"<p>Japanese networks grow from factory control, bank and trading-company transactions, shipping, inventory, railway reservations, and imperial logistics. They are optimized for controlled procedures and high-volume institutional exchanges rather than arbitrary independent hosts.</p>"},
      {id:"households",title:"Paging and household services",html:"<p>Paging, commercial orders, integrated terminals, consumer electronics, and intermittently connected devices bring the system into ordinary life. A person, household, ship, office, or mobile terminal may receive a stored message when it next reaches a gateway.</p>"},
      {id:"text",title:"Native-text engineering",html:"<p>Japanese computing must handle kana, ideographs, vertical and horizontal text, complex line breaking, and the scripts of an unequal multilingual sphere. That pressure makes UNICODE 80, character-cell negotiation, compact regional encodings, and device descriptions practical necessities rather than optional international features.</p>"},
      {id:"institutions",title:"Corporate and state control",html:"<p>Zaibatsu networks, ministries, banks, household subscriptions, employers, and licensed service firms identify most ordinary users through application accounts. The public experience is orderly and attributable even though the later shared transport does not itself enforce real-world identity.</p>"},
      {id:"convergence",title:"Convergence with Weltnetz",html:"<p>From 1986 to 1988, Japanese requirements for multilingual display, delayed delivery, mobile endpoints, compact terminals, and household services enter the common German-led protocol family. Japan supplies much of the practical electronics and presentation system while accepting Weltnetz carriage.</p>"},
      {id:"name",title:"Teikoku Jōhōmō and Sekaimō",html:"<p><em>Teikoku Jōhōmō</em> (‘Imperial Information Network’) describes the earlier national system. <em>Sekai Jōhōmō</em>, commonly shortened to <strong>Sekaimō</strong> (‘world net’), becomes the Japanese public presentation of the converged system. It is not a separate global protocol after the late 1980s.</p>"},
      {id:"sphere",title:"Unequal sphere implementation",html:"<p>Japan proper receives the richest terminals, directories, service integration, and technical authority. Chōsen and Taiwan are integral regions; Manchukuo, China, the Philippines, and the Mekong states connect through corporate and national layers with different degrees of local language and administrative control.</p>"},
      {id:"position",title:"Position after convergence",html:"<p>Japan does not win the name of the world protocol but makes that protocol capable of carrying the world’s writing and household devices. Japanese platforms, search services, payment systems, publishers, and corporate networks remain nationally governed above the common road.</p>"}
    ],
    related:[{href:"japan.html",kicker:"National setting",label:"Empire of Japan"},{href:"weltnetz.html",kicker:"Converged transport",label:"Weltnetz"},{href:"unicode-80.html",kicker:"Character foundation",label:"UNICODE 80"},{href:"japanese-programming-languages.html",kicker:"Software culture",label:"Japanese Programming Languages"},{href:"software-localization-in-mekong-states.html",kicker:"Associated-state application",label:"Mekong Software Localization"}],
    facts:[["Working formal name","Teikoku Jōhōmō"],["Converged public name","Sekaimō"],["Origins","Factories, finance, shipping, logistics"],["Consumer strengths","Paging and household terminals"],["Character standard","UNICODE 80"],["Convergence period","1986–1988"],["Transport after convergence","Weltnetz"],["Separate post-convergence protocol","No"]]
  }),

  "latin-technical-network":networkArticle({
    slug:"latin-technical-network",title:"Latin Technical Network",eyebrow:"Confederal public and professional network · 1970s–1990s",infoboxKicker:"Latin-bloc network ecology",
    lead:"The Latin Technical Network is the confederal network ecology built from Olivetti business systems, Italian state corporations, Scudo clearing, ports, Occitan scientific computing, Iberian telecommunications, and public administrative services. Rete Pubblica Latina or Rete Latina is common Italian-led usage, not a claim that Rome owns the bloc’s information system.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-n7p8q writer=g kind=revision created=2026-08-15T22:55:00-06:00 -->A distinct, somewhat later Latin public-network ecology exists by 1985, exchanges traffic through gateways, and survives above Weltnetz after adopting its international carriage.<sup class='canon-note' data-provenance='a'>[a]</sup> Its Olivetti, state-corporate, Scudo, port, scientific and telecommunications ancestry; structured-professional strengths; confederal governance; household timing; search controls; and the names Latin Technical Network, Rete Pubblica Latina and Rete Latina remain working elaboration. A legal name, treaty basis, and carrier list are open.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"origins",title:"A confederal origin",html:"<p>The network grows from Olivetti office machines, Italian public corporations, banking and <a href='latin-scudo.html'>Scudo</a> settlement, ports and shipping, Occitan scientific systems, and Spanish and Portuguese telecommunications. No single ministry can simply nationalize the entire ecology.</p>"},
      {id:"names",title:"Rete Latina and national names",html:"<p><em>Rete Pubblica Latina</em> and the shorter <em>Rete Latina</em> are common technical and Italian institutional terms. Spanish, Portuguese, and Occitan operators use their own translations and service brands. The shared label describes compatibility and governance agreements, not Italian sovereignty.</p>"},
      {id:"strengths",title:"Forms, law, and professional data",html:"<p>Latin systems are especially strong in structured forms, professional databases, legal and accounting records, customs, public terminals, commercial logic, engineering documents, and multilingual publication. They are slower than America and Japan to become an ordinary household medium.</p>"},
      {id:"money",title:"Scudo settlement",html:"<p>Banking and trade services treat the Latin Scudo as a common legal and accounting object while preserving national taxes, courts, budgets, and institutions. Exact decimal arithmetic, auditable conversion, and recoverable transactions make <a href='lia-language.html'>LIA</a> an important administrative substrate.</p>"},
      {id:"public",title:"Public-service terminals",html:"<p>Municipal offices, professional associations, ports, utilities, banks, universities, and cultural institutions provide named services through licensed terminals and office machines. Access is comparatively coherent but remains conditioned by country, profession, and carrier.</p>"},
      {id:"weltnetz",title:"Weltnetz adoption",html:"<p>Latin firms and institutions adopt Weltnetz for external internetworking during the early 1990s because German, Japanese, British, and American Bridge partners already use it. Local applications, records, authentication, and public services continue unchanged behind the gateway.</p>"},
      {id:"search",title:"Licensed discovery",html:"<p>Latin search and directory services favor professional, cultural, legal, commercial, ecclesiastical, and state sources. Bulk foreign indexing may be licensed or restricted. Foreign engines are reachable, but they do not automatically possess the metadata or rights needed to describe domestic services well.</p>"},
      {id:"position",title:"Position after convergence",html:"<p>The Latin network becomes a confederal service layer over common carriage, not a relic displaced by it. Its achievement is making international interoperability compatible with continued public-law and professional control in several national languages.</p>"}
    ],
    related:[{href:"latin-bloc.html",kicker:"Political system",label:"Latin Bloc"},{href:"weltnetz.html",kicker:"External carriage",label:"Weltnetz"},{href:"latin-programming-languages.html",kicker:"Software ecology",label:"Latin-bloc Programming Languages"},{href:"lia-language.html",kicker:"Administrative substrate",label:"LIA"},{href:"national-network-search-services.html",kicker:"Discovery layer",label:"National Network Search Services"}],
    facts:[["Common collective name","Latin Technical Network"],["Italian usage","Rete Pubblica Latina / Rete Latina"],["Political form","Confederal"],["Principal strengths","Forms, law, finance, professional data"],["Monetary system","Latin Scudo"],["Administrative language","LIA"],["Household adoption","Comparatively late"],["External layer after convergence","Weltnetz"]]
  }),

  "national-network-search-services":networkArticle({
    slug:"national-network-search-services",title:"National network search services",eyebrow:"Discovery, directories, and political borders · 1980s–2000s",infoboxKicker:"Search and directory systems",
    lead:"National network search services are the competing public maps of Weltnetz. The common transport standard never produces one universal global index: German, Japanese, American, Commonwealth, and Latin services rank, certify, translate, license, omit, and monetize different portions of the same reachable network.",
    canon:"<!-- altwwii-writer-block:start id=wb-g-20260815-n8r9s writer=g kind=revision created=2026-08-15T22:55:00-06:00 -->National rather than universal search is established, as are Germany's unusually controlled and security-focused system, multiple competing American engines, a Japanese equivalent, and the possibility of reaching foreign or unlisted services over Weltnetz.<sup class='canon-note' data-provenance='a'>[a]</sup> The exact German certification system, Japanese household integration, Commonwealth reference-and-translation role, Latin licensed professional directories, crawler and ranking rules, border mechanisms, institutional or product names, and complete search chronology remain working extrapolation.<sup class='canon-note' data-provenance='e'>[e]</sup><!-- altwwii-writer-block:end -->",
    sections:[
      {id:"not-network",title:"A search service is not the network",html:"<p>Weltnetz defines addressing, transfer, messages, documents, and service conventions. Search decides what a user can discover without already knowing an address. A service omitted from a national engine may remain reachable through a direct address, foreign directory, printed list, private message, or relay.</p>"},
      {id:"germany",title:"Germany: security and certification",html:"<p>Germany’s principal directory emphasizes registered publishers, official services, certified commerce, malware warnings, software signatures, and state-authorized access. <em>Deutsches Netzregister</em> is a working institutional name. Licensed providers present it by default and may block addresses formally listed by security authorities.</p>"},
      {id:"japan",title:"Japan: language and integrated services",html:"<p>Japanese search integrates native text, vertical layout, household subscriptions, shopping, transport, publishers, bank services, and Co-Prosperity directories. Corporate groups and ministries strongly shape visibility even though technically skilled users can reach unlisted foreign services.</p>"},
      {id:"america",title:"United States: competing commercial engines",html:"<p>American companies compete over advertising, independent publishers, commercial pages, software catalogs, popularity signals, and Bridge-hosted services. There is no single national gatekeeper. Rankings are innovative, purchasable, manipulable, and divided among firms with different political and corporate alliances.</p>"},
      {id:"britain",title:"Commonwealth: reference and translation",html:"<p>Commonwealth services emphasize libraries, education, public information, shipping, insurance, government records, and multilingual gateways. Their value often lies in describing and translating systems that a purely domestic engine cannot interpret.</p>"},
      {id:"latin",title:"Latin bloc: licensed professional discovery",html:"<p>Latin services foreground professional, cultural, legal, ecclesiastical, commercial, and government directories. National and confederal authorities may charge for bulk indexing, restrict reuse of official metadata, or require a foreign engine to operate through a licensed local partner.</p>"},
      {id:"borders",title:"Why one global engine does not emerge",html:"<p>Language, script, law, licensing, payment, gateway cost, crawler permission, political filtering, and incompatible ranking metadata preserve borders. A German engine may not be permitted to crawl Japanese household services; an American engine may index Latin public records poorly; a Japanese engine may be irrelevant to an ordinary British school user.</p>"},
      {id:"shadow",title:"The unlisted network",html:"<p><a href='shadownet.html'>ShadowNet</a> grows in the space outside ordinary indexes: private boards, invitation communities, relays, temporary stores, political archives, piracy, illicit trade, and anonymous publication. Governments control what most users find first more easily than they control everything Weltnetz can carry.</p>"}
    ],
    related:[{href:"weltnetz.html",kicker:"Underlying transport",label:"Weltnetz"},{href:"shadownet.html",kicker:"Unlisted culture",label:"ShadowNet"},{href:"american-data-network.html",kicker:"American precursor",label:"American Data Network"},{href:"japanese-imperial-information-network.html",kicker:"Japanese service ecology",label:"Japanese Imperial Information Network"},{href:"commonwealth-packet-service.html",kicker:"Reference culture",label:"Commonwealth Packet Service"}],
    facts:[["Universal global engine","Absent"],["German emphasis","Certification and security"],["Japanese emphasis","Language and household services"],["American emphasis","Commercial competition"],["Commonwealth emphasis","Reference and translation"],["Latin emphasis","Licensed professional directories"],["Unindexed overlay","ShadowNet"],["Core distinction","Search maps the network; it is not the network"]]
  })
});

const addNetworkRelated = (slug,item) => {
  const related = window.deepArticles[slug]?.related;
  if (related && !related.some(entry=>entry.href===item.href)) related.unshift(item);
};

