const falkenberg = window.deepArticles["matthias-falkenberg"];
if (falkenberg) {
  falkenberg.lead = "Matthias Falkenberg is the principal architect of Weltnetz, the German network federation that becomes the common international carriage layer. He favors registered machines, certified gateways, identified subscribers, and hierarchical administration; his historical importance lies in accepting a transport standard that cannot guarantee those conditions and is therefore usable beyond German control.";
  falkenberg.canon = "His biography, politics, 1979–85 development chronology, post-1985 network-layer victory, and disappointment with the adopted identity compromise are canon. Exact later offices, retirement, and public interventions remain open.";
  const weltnetzSection = falkenberg.sections.find(section=>section.id==="weltnetz");
  if (weltnetzSection) weltnetzSection.html = "<p>Falkenberg expands civilian Planform, software houses, satellite gateways, and partner networks. Orbital imagery wins patronage, though most traffic moves by cable, microwave, fiber, and local packets. Early German traffic is identified because users enter through known institutions—not because every packet proves civil identity.</p>";
  if (!falkenberg.sections.some(section=>section.id==="compromise")) falkenberg.sections.push({id:"compromise",title:"Engineering triumph, governing disappointment",html:"<p>Japanese household access and American Bridge software make permanent machine registration untenable. Falkenberg accepts a compact transport layer without mandatory real-world identity because the alternative is a legible German network that no foreign market adopts. Weltnetz becomes a German prestige victory and one of the few great German institutions the state cannot govern according to its original assumptions.</p><p>His later judgment is that Weltnetz succeeded as engineering and failed as government.</p>"});
}

const networkOverview = window.deepArticles["computing-networks"];
if (networkOverview) {
  networkOverview.lead = "Computer networks begin as five separate institutional worlds. During the late 1980s and 1990s they converge on Weltnetz as a common international transport layer while preserving national carriers, strategic backbones, operating systems, search services, identity regimes, and public laws.";
  networkOverview.canon = "The five independent beginnings, gatewayed 1985 order, Weltnetz convergence, nonmandatory base-layer identity, national service survival, and later ShadowNet culture are canon. Low-level protocol names and most carrier and search-company identities remain open.";
  networkOverview.sections = [
    {id:"beginnings",title:"Five independent beginnings",html:"<p>From the late 1960s, the <a href='american-data-network.html'>American Data Network</a>, German imperial computer federation, <a href='commonwealth-packet-service.html'>Commonwealth Packet Service</a>, Japanese Imperial Information Network, and Latin Technical Network develop independently. Each solves packet sharing, remote service, and unreliable communication for its own institutions.</p>"},
    {id:"germany",title:"Germany: administration across distance",html:"<p>German networks connect military command, aerospace, rail, commodities, banks, industrial combines, eastern administrations, and Mittelafrika. Falkenberg turns that infrastructure into <a href='weltnetz.html'>Weltnetz</a>, a satellite-centered hybrid designed to join heterogeneous machines over immense and politically awkward distances.</p>"},
    {id:"america",title:"America: open institutional experimentation",html:"<p>The ADN grows among defense, universities, contractors, manufacturers, banks, government, media, and dial-up communities. It is inventive and decentralized but weak at international text, billing, directories, and administration. Bridge/WN later carries its civilian ecosystem onto Weltnetz while a strategic backbone remains separate.</p>"},
    {id:"japan",title:"Japan: transactions, households, and text",html:"<p>Japanese networks integrate factories, shipping, rail, banks, paging, shopping, and household terminals. Their multilingual character and device work gives UNICODE 80, writing direction, delayed delivery, and compact endpoints a decisive place in the converged system.</p>"},
    {id:"commonwealth",title:"Commonwealth: managed information service",html:"<p>Britain joins unlike machines through time sharing, public packet services, videotex, education, ports, finance, government, and translation. The CPS lacks German physical reach and Japanese terminal scale but remains an influential gateway, caching, and reference culture.</p>"},
    {id:"latin",title:"Latin bloc: public and professional coordination",html:"<p>The Latin Technical Network joins Olivetti systems, Scudo settlement, ports, state corporations, public terminals, legal records, and professional databases through confederal rules. It later adopts Weltnetz carriage without surrendering national applications or licensing.</p>"},
    {id:"convergence",title:"Convergence without a universal service",html:"<p>German–Japanese cooperation, Bridge/WN, Concord support, UNICODE carriage, and common document standards make Weltnetz the default international civilian layer by the mid-1990s. Physical carriers and local networks survive as portions of the common road rather than being dismantled.</p>"},
    {id:"borders",title:"Search, identity, and political borders",html:"<p>The transport layer does not mandate civil identity and no global search engine indexes everything. Providers, banks, employers, and states build authentication and control above it. National search systems define ordinary visibility; unlisted relays and pseudonymous services develop into <a href='shadownet.html'>ShadowNet</a> and foreign equivalents.</p>"},
    {id:"productive-capacity",title:"Productive capacity of convergence",html:"<!-- altwwii-writer-block:start id=wb-k-20260816-q9d4s writer=k kind=analysis created=2026-08-16T13:59:00-06:00 --><p>Weltnetz's economic return cannot be read from carrier revenue alone. A common carriage layer allowed an existing cable, radio, satellite, switching, computing, and service establishment to reach users outside its original bloc without replacing their machines or applications. The capability created was interoperable exchange: firms could address a wider market, banks and carriers could coordinate transactions, distant institutions could share records, and software or information services could add foreign users through gateways. Each later use drew upon the same standards, routes, directories, trained operators, repair organizations, and cached material.</p><p>Convergence removed translation and reach as recurrent bottlenecks but did not abolish physical scarcity. Useful capacity depended upon terrestrial trunks, satellite coverage, local access, gateway processing, electric power, spares, and personnel able to restore service. Redundant routing and caching reduced the consequence of a failed long route only where alternate paths had genuine headroom and current copies. A resilience account therefore asked how much priority traffic survived the loss of a cable, satellite, gateway, or major node; how long restoration took; and which regions were shed first when capacity became scarce.</p><div class='table-wrap'><table class='wiki-table'><thead><tr><th>Claim</th><th>Capability evidence</th><th>Accounting discipline</th></tr></thead><tbody><tr><td>Common carriage enlarged production</td><td>New cross-bloc customers, suppliers, services, and transactions became usable through existing systems</td><td>Separate additional traffic and downstream use from traffic merely shifted between carriers</td></tr><tr><td>Standards reduced dependence</td><td>More than one supplier could build, test, repair, or replace conforming gateways and terminals</td><td>Disclose patents, certification delays, proprietary extensions, and any single-source component</td></tr><tr><td>Redundancy preserved continuity</td><td>Priority service continued under a defined route or node failure and met a stated restoration time</td><td>Publish outages, congestion, reserve utilization, repair cost, and traffic denied to ordinary users</td></tr><tr><td>Coverage enabled distant activity</td><td>Previously isolated firms and institutions gained reliable access at a known quality</td><td>Show the subsidy, installation queue, service quality, and alternative local investments displaced</td></tr></tbody></table></div><p>Public direction could set open interfaces, interconnection duties, emergency priorities, coverage floors, continuity standards, and migration dates. Carriers and firms retained network construction, equipment design, software, maintenance methods, retail services, and ordinary pricing. This boundary mattered because a standard that guaranteed one incumbent's equipment, a directory that concealed rivals, or a reserve budget without failure tests converted coordination into protection of management. Failed suppliers still required replacement, and prices still had to reveal congestion and the cost of scarce capacity.</p><p>The common layer also concentrated dependencies. German standards and satellite reach could reduce every participant's translation costs while giving German institutions influence over certification, maps, and chokepoints; national backbones and gateways were therefore insurance as well as political boundaries. Nor did wider connection settle the allocation question. Households and small firms might prefer cheaper local service, privacy, or faster access to scarce lines over imperial coverage, security logging, or reserve routes. Unequal access, surveillance, censorship, and the first users disconnected in a crisis belonged in the capability account rather than outside it.</p><!-- altwwii-writer-block:end -->"}
  ];
  networkOverview.related = [
    {href:"weltnetz.html",kicker:"Common international layer",label:"Weltnetz"},
    {href:"american-data-network.html",kicker:"American precursor",label:"American Data Network"},
    {href:"commonwealth-packet-service.html",kicker:"British system",label:"Commonwealth Packet Service"},
    {href:"japanese-imperial-information-network.html",kicker:"Japanese system",label:"Japanese Imperial Information Network"},
    {href:"latin-technical-network.html",kicker:"Latin system",label:"Latin Technical Network"},
    {href:"national-network-search-services.html",kicker:"Discovery layer",label:"National Network Search Services"}
  ];
  networkOverview.facts = [["Independent network cultures","Five"],["Common layer in 1985","Absent"],["Winning international family","Weltnetz"],["Convergence period","Late 1980s–mid-1990s"],["Mandatory base identity","Absent"],["American civilian gateway","Bridge/WN"],["Universal search engine","Absent"],["Strategic national networks","Retained"]];
}
